'use strict';
const C=window.Craft,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n).toLocaleString('zh-TW'),today=()=>C.date(),weekday=d=>'日一二三四五六'[new Date(d+'T12:00:00').getDay()],shortDate=d=>`${Number(d.slice(5,7))}/${Number(d.slice(8))}（${weekday(d)}）`;
let db,blocked=false,page='home',courseTab='list',filter='',search='',studentSearch='',calendarMonth=today().slice(0,7),selectedDate=today(),statsMonth=today().slice(0,7),editing=null,formPhoto='',modalContext=null,toastTimer,swReady=false;
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',book:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 3v18m4-12h5m-5 5h5"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3q4 1 3 7"/>',chart:'<path d="M4 4v17h17M9 16v-5m5 5V6m5 10v-8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18m-13 5h2m4 0h2"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9m3-10v12"/>',check:'<path d="m5 12 4 4L19 6"/>',leaf:'<path d="M19 4Q4 2 5 15q11 7 14-11ZM5 20l9-11"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const btn=(label,action,id='',cls='secondary')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const pill=(s)=>`<span class="pill ${['已成班','已完成','已付款','✓ 材料準備完成','可以招生'].includes(s)?'green':['準備招生','未付款'].includes(s)?'pink':s==='招生中'?'orange':s==='已額滿'?'tea':''}">${esc(s)}</span>`;
const findCourse=id=>db.sessions.find(c=>c.id===id),findStudent=id=>db.students.find(s=>s.id===id);
const countChecks=xs=>xs.filter(Boolean).length;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function warning(message){$('#storage-warning').hidden=!message;$('#storage-warning').textContent=message}
function load(){try{const raw=localStorage.getItem(C.KEY);db=raw?C.validate(JSON.parse(raw)):C.seed();if(!raw)localStorage.setItem(C.KEY,JSON.stringify(db))}catch(e){blocked=true;db=C.blank();warning('本機資料無法讀取或儲存，原資料未覆蓋。請至設定匯出原始資料或匯入有效備份。'+e.message)}}
function commit(fn){if(blocked)throw Error('目前為資料保護模式，請先從設定匯入有效備份。');const latest=localStorage.getItem(C.KEY);if(latest&&JSON.parse(latest).revision!==db.revision)throw Error('另一個分頁已更新資料。請關閉表單並重新整理後再修改。');const next=C.clone(db);fn(next);next.revision++;C.validate(next);try{localStorage.setItem(C.KEY,JSON.stringify(next))}catch{throw Error('儲存空間不足或瀏覽器禁止保存。此次修改尚未儲存，請先匯出備份，減少照片後再試。')}db=next;render()}
function showSheet(title,html,context=null){modalContext=context;$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;if(!$('#sheet').open)$('#sheet').showModal();$('#sheet').scrollTop=0;const auto=$('#sheet [autofocus]');if(auto)auto.focus()}
function closeSheet(){if($('#sheet form')&&!confirm('關閉編輯視窗？尚未儲存的修改將不保留。'))return;$('#sheet').close();modalContext=null}
function empty(text,button=''){return `<div class="empty">${text}${button?'<br>'+button:''}</div>`}
function thumb(c,large=false){return c.photo?`<button type="button" class="photo-btn ${large?'hero-photo':''}" data-action="photo" data-id="${esc(c.id)}" aria-label="放大${esc(c.name)}作品照片"><img src="${esc(c.photo)}" alt="${esc(c.name)}作品"></button>`:`<img src="assets/bag.svg" alt="布藝手作插畫">`}
function courseRow(c){return `<button class="course-row" data-action="course-detail" data-id="${c.id}"><span class="date-block"><small>週${weekday(c.date)}</small><strong>${Number(c.date.slice(8))}</strong></span><span class="row-main"><h3>${esc(c.name)}</h3><small>${c.start}–${c.end} · ${esc(c.level)}</small></span><span class="row-side">${pill(C.status(db,c))}<small>${C.active(db,c.id).length}／${c.capacity} 人</small></span><span class="arrow">›</span></button>`}
function weekBounds(){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));const first=C.date(d);d.setDate(d.getDate()+6);return [first,C.date(d)]}
function home(){const [first,last]=weekBounds(),week=db.sessions.filter(c=>c.date>=first&&c.date<=last).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start));const upcoming=db.sessions.filter(c=>!['取消','已完成','未開課'].includes(c.status)&&new Date(c.date+'T'+c.end)>new Date()).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),c=upcoming[0];const es=c?C.active(db,c.id):[],due=es.filter(e=>!C.paid(db,e)),materials=c?countChecks(c.materials):0;
let slots='';for(const day of [1,3]){const d=new Date(first+'T12:00:00');d.setDate(d.getDate()+day);const ds=C.date(d);if(!week.some(c=>c.date===ds))slots+=`<button class="course-row" data-action="new-course-date" data-id="${ds}"><span class="date-block"><small>週${weekday(ds)}</small><strong>${d.getDate()}</strong></span><span class="row-main"><h3>留一個手作的午後</h3><small>13:00–15:00 · 尚未安排</small></span><span class="pill">未開課</span><span class="arrow">＋</span></button>`}
return `<div class="page-head"><div><p class="eyebrow">A LITTLE JOY, HANDMADE.</p><h1>采卉手作課程</h1><p class="subtitle">用布，做生活裡的小美好</p></div><span class="date-label">${new Date().getFullYear()} 年 ${shortDate(today())}</span></div>
${c?`<section class="hero"><div class="hero-content"><p class="hero-label">${icon('calendar')} 下一堂課 ${c.demo?'· 示範':''}</p><div class="hero-time"><strong>${shortDate(c.date)}</strong><span>｜</span><span>${c.start}–${c.end}</span></div><h2>${esc(c.name)}</h2><p><strong>${es.length}／${c.capacity}</strong> 人 <span class="muted">・${esc(c.level)}也能輕鬆開始</span></p><div class="hero-badges">${pill(C.status(db,c))}${pill(materials===10?'✓ 材料準備完成':`材料準備 ${materials}／10`)}${due.length?pill(`${due.length} 人待付款`):pill('已付款')}</div><div class="button-row">${btn('查看課程 →','course-detail',c.id,'')}${btn('＋ 新增學員','enroll',c.id)}</div></div><div class="hero-art">${thumb(c,true)}<span class="art-caption">STITCH A LITTLE HAPPINESS</span></div></section>`:empty('下一個手作的午後，等你來安排。',btn('＋ 新增課程','new-course','',''))}
<div class="summary-grid"><button class="summary" data-action="nav" data-value="courses"><span class="summary-icon">${icon('calendar')}</span><div><strong>${week.filter(c=>!['取消','未開課'].includes(c.status)).length}</strong> <small>本週課程</small></div></button><button class="summary" data-action="unpaid"><span class="summary-icon">${icon('coin')}</span><div><strong>${new Set(db.payments.filter(p=>!p.paid&&!p.void).map(p=>p.studentId)).size}</strong> <small>學員待付款</small></div></button><button class="summary" data-action="${c?'course-detail':'new-course'}" data-id="${c?.id||''}"><span class="summary-icon">${icon('leaf')}</span><div><strong>${materials}<span style="font-size:.8rem">／10</span></strong><small>下堂材料準備</small></div></button></div>
<div class="dashboard-bottom"><section><div class="section-head"><h2>本週的小美好 <small>${first.slice(5).replace('-','/')}–${last.slice(5).replace('-','/')}</small></h2><button class="text-btn" data-action="calendar">月曆 ${icon('calendar')}</button></div><div class="week-list">${week.map(courseRow).join('')}${slots}</div></section><section><div class="section-head"><h2>手作小幫手</h2></div><div class="quick-card"><h3>好好準備，慢慢手作。</h3><p>把課前瑣事整理好，把時間留給喜歡的事。</p>${btn('＋ 新增課程','new-course')}${btn('＋ 新增學員','new-student')}</div></section></div><p class="home-footer">一針一線，都是生活的溫柔 ♡</p>`}
function courses(){return `<div class="page-head"><div><p class="eyebrow">MAKE TIME TO CREATE</p><h1>課程手帳</h1><p class="subtitle">安排一個午後，完成一份小美好。</p></div>${btn('＋ 開新課','new-course','','')}</div><div class="tabs" role="tablist" aria-label="課程檢視">${[['list','課程列表'],['calendar','月曆'],['templates','課程範本']].map(([v,l])=>`<button role="tab" aria-selected="${courseTab===v}" class="${courseTab===v?'active':''}" data-action="course-tab" data-value="${v}">${l}</button>`).join('')}</div>${courseTab==='calendar'?calendar():courseTab==='templates'?templates():`<div class="toolbar"><input class="search" id="course-search" aria-label="搜尋課程" placeholder="搜尋課程名稱…" value="${esc(search)}"><select id="course-filter" aria-label="篩選課程狀態"><option value="">全部狀態</option>${C.STATUS.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="course-grid" id="course-results">${courseResults()}</div>`}`}
function courseResults(){const cs=db.sessions.filter(c=>(!filter||C.status(db,c)===filter)&&c.name.includes(search)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));return cs.map(c=>`<article class="card course-card"><header><div class="course-thumb">${thumb(c)}</div><div class="row-main"><h3>${esc(c.name)}</h3><div class="meta-line">${esc(c.level)} ${c.demo?'· 示範':''}</div></div></header><div class="meta-line">${icon('calendar')}${shortDate(c.date)} · ${c.start}–${c.end}</div><div class="meta-line">${pill(C.status(db,c))}<span>${C.active(db,c.id).length}／${c.capacity} 人</span><span>材料 ${countChecks(c.materials)}／10</span></div><div class="card-foot"><small>材料包 ${money(C.kit(db,c).price)}</small>${btn('查看課程 →','course-detail',c.id,'secondary small')}</div></article>`).join('')||empty('目前沒有符合的課程。',btn('＋ 新增課程','new-course'))}
function templates(){return `<p class="note" style="margin-bottom:18px">設定一次作品、材料與工具，下次只要選日期就能開課。</p><div class="course-grid">${db.templates.map(t=>`<article class="card course-card"><header><div class="course-thumb">${thumb(t)}</div><div><h3>${esc(t.name)}</h3><small>${esc(t.level)} · ${esc(t.difficulty)}</small></div></header><p class="muted">${esc(C.kit(db,t).name)} · ${money(C.kit(db,t).price)}</p><small>材料費參考 ${esc(t.reference||'依店家設定')}，可自由調整</small><div class="button-row">${btn('編輯範本','edit-template',t.id)}${btn('用此範本開課','use-template',t.id,'')}</div></article>`).join('')}</div><div class="section-head">${btn('＋ 自訂課程範本','new-template')}</div>`}
function calendar(){const [year,month]=calendarMonth.split('-').map(Number),offset=(new Date(year,month-1,1).getDay()+6)%7,days=new Date(year,month,0).getDate();return `<div class="month-nav"><button class="icon-btn" data-action="month-prev" aria-label="上個月">‹</button><h2>${year} 年 ${month} 月</h2><button class="icon-btn" data-action="month-next" aria-label="下個月">›</button></div><div class="calendar">${'一二三四五六日'.split('').map(d=>`<div class="weekday">${d}</div>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=calendarMonth+'-'+String(i+1).padStart(2,'0'),cs=db.sessions.filter(c=>c.date===d);return `<button class="day ${d===today()?'today':''} ${d===selectedDate?'selected':''}" data-action="select-date" data-id="${d}" aria-label="${shortDate(d)}，${cs.length} 堂課" aria-pressed="${d===selectedDate}">${i+1}<span class="dots">${cs.slice(0,4).map(c=>`<span class="dot ${c.status==='取消'?'cancel':''}"></span>`).join('')}</span></button>`}).join('')}</div><div class="section-head"><h2>${shortDate(selectedDate)}</h2>${btn('＋ 新增課程','new-course-date',selectedDate,'secondary small')}</div><div class="week-list">${db.sessions.filter(c=>c.date===selectedDate).map(courseRow).join('')||empty('這一天尚未安排課程。')}</div>`}
function studentCard(s){const es=db.enrollments.filter(e=>e.studentId===s.id&&!e.cancelled),attended=db.enrollments.filter(e=>e.studentId===s.id&&(e.attended||e.wasAttended)).length,ps=db.payments.filter(p=>p.studentId===s.id&&!p.void),pkgs=db.packages.filter(p=>p.studentId===s.id&&!p.closed&&C.used(db,p)<2),next=es.map(e=>findCourse(e.sessionId)).filter(c=>c.date>=today()&&!['取消','已完成'].includes(c.status)).sort((a,b)=>a.date.localeCompare(b.date))[0];return `<article class="card student-card"><header><span class="avatar">${esc(s.name.slice(0,1))}</span><div class="row-main"><h3>${esc(s.name)}</h3><small>已上課 ${attended} 堂 ${s.demo?'· 示範學員':''}</small></div>${ps.some(p=>!p.paid)?pill('未付款'):pill('已付款')}</header><p>${next?`${shortDate(next.date)} ${esc(next.name)}`:'目前沒有待上課程'}</p>${pkgs.map(p=>`<div class="meta-line">${pill('兩堂方案')} ${C.used(db,p)}／2 已使用</div>`).join('')}<div class="card-foot" style="margin-top:17px"><small>累計淨收 ${money(ps.reduce((a,p)=>a+C.paymentNet(db,p),0))}</small>${btn('查看學員 →','student-detail',s.id,'secondary small')}</div></article>`}
function students(){return `<div class="page-head"><div><p class="eyebrow">FAMILIAR FACES, HAPPY MOMENTS</p><h1>一起手作的人</h1><p class="subtitle">${db.students.length} 位學員，每一次相聚都值得記得。</p></div>${btn('＋ 新增','new-student','','')}</div><div class="toolbar"><input id="student-search" class="search" placeholder="搜尋姓名、暱稱、電話或 LINE…" aria-label="搜尋學員" value="${esc(studentSearch)}"></div><div class="student-grid" id="student-results">${studentResults()}</div>`}
function studentResults(){return db.students.filter(s=>[s.name,s.nickname,s.phone,s.lineName].some(v=>v.includes(studentSearch))).map(studentCard).join('')||empty('還沒有符合的學員。',btn('＋ 新增學員','new-student'))}
function trendChart(rows,mode){
 const keys=mode==='money'?['grossTotal','refundTotal']:['courses','students'],labels=mode==='money'?['收款','退費']:['開課','人次'],max=Math.max(1,...rows.flatMap(r=>keys.map(k=>r[k])));
 return `<div class="chart-legend"><span><i class="legend-dot sage"></i>${labels[0]}</span><span><i class="legend-dot blush"></i>${labels[1]}</span></div><div class="bar-chart" role="group" aria-label="最近六個月${labels.join('與')}圖表">${rows.map(r=>`<button class="chart-month ${r.month===statsMonth?'selected':''}" data-action="stats-select-month" data-id="${r.month}" aria-label="${r.month}：${labels[0]} ${r[keys[0]]}，${labels[1]} ${r[keys[1]]}，點擊查看"><span class="bar-pair">${keys.map((k,i)=>`<span class="bar-track"><span class="chart-value">${mode==='money'?money(r[k]):r[k]}</span><span class="chart-bar ${i?'blush':'sage'}" style="height:${r[k]/max*100}%" aria-hidden="true"></span></span>`).join('')}</span><span class="chart-month-label">${r.month.slice(5)} 月</span></button>`).join('')}</div><details class="chart-data"><summary>查看完整數字</summary><div class="mini-list">${rows.map(r=>`<p>${r.month}　${labels[0]} ${mode==='money'?money(r[keys[0]]):r[keys[0]]} · ${labels[1]} ${mode==='money'?money(r[keys[1]]):r[keys[1]]}</p>`).join('')}</div></details>`;
}
function costChart(s){const rows=[['課程收款',s.grossTuition,'sage'],['材料收款',s.grossMaterial,'tea'],['材料成本',s.cost,'blush']],max=Math.max(1,...rows.map(r=>r[1]));return `<div class="cost-chart" role="group" aria-label="本月課程收款、材料收款與材料成本">${rows.map(([l,v,color])=>`<div class="cost-chart-row"><div class="price-line"><span>${l}</span><strong>${money(v)}</strong></div><div class="cost-track"><span class="${color}" style="width:${v/max*100}%"></span></div></div>`).join('')}</div><p class="hint">材料退費 ${money(s.materialRefund)} · 退費後材料毛利 ${money(s.profit)}</p>`}
function statsPage(){const s=C.stats(db,statsMonth),rows=C.monthlyTrend(db,statsMonth);return `<div class="page-head"><div><p class="eyebrow">SMALL MOMENTS, GROWING TOGETHER</p><h1>這個月的收穫</h1><p class="subtitle">收進多少、退回多少，每筆都有依據。</p></div></div><div class="toolbar"><label>查看月份<input id="stats-month" type="month" value="${statsMonth}"></label>${btn('退費／結算','refund-center','','secondary')}${btn('退費紀錄','refund-history','','secondary')}</div><div class="stat-grid">${[['本月開課',s.courses+' 堂'],['總學員',s.students+' 人次'],['本月收款',money(s.grossTotal)],['本月退費',money(s.refundTotal)],['退費後淨收入',money(s.total)],['課程淨收入',money(s.tuition)],['材料淨收入',money(s.material)],['材料成本',money(s.cost)],['材料毛利',money(s.profit)]].map(([l,v],i)=>`<div class="card stat-card ${i===4?'total':''}"><p>${l}</p><strong>${v}</strong></div>`).join('')}</div><div class="chart-layout"><section class="card chart-card"><h3>近六個月 · 收款與退費</h3><p class="hint">點月份可查看該月；退費按實際退款日計入。</p>${trendChart(rows,'money')}</section><section class="card chart-card"><h3>本月 · 收入與材料成本</h3>${costChart(s)}</section><section class="card chart-card span-chart"><h3>近六個月 · 開課與人次</h3>${trendChart(rows,'classes')}</section></div><section class="card" style="margin-top:20px"><h3>帳目怎麼看</h3><p class="hint">收款按收款日，退費按退款日分別記錄。淨收入＝收款－退費；跨月退款可能使當月淨收入為負。兩堂方案費只收一次。材料成本依當月有效報名與已交付／使用材料的成本快照，取消不會抹除已交付材料成本。這是簡單收支統計，並非完整會計損益。</p><div class="section-head"><h3>全部待收款 ${money(s.outstanding)}</h3>${btn('查看明細','unpaid','','secondary small')}</div></section>`}
function settings(){return `<div class="page-head"><div><p class="eyebrow">KEEP YOUR LITTLE JOYS SAFE</p><h1>設定與資料備份</h1><p class="subtitle">把珍貴的手作紀錄，好好收著。</p></div></div><section class="card settings-block"><h2>只存在這台裝置的手帳</h2><p>課程、學員與照片保存在目前瀏覽器，不會跨裝置同步。清除瀏覽器網站資料會刪除紀錄，建議每週下載一份備份。</p><div class="button-row">${btn('↓ 匯出備份','export','','')}${btn('↑ 匯入備份','import')}</div><p class="hint">匯入會先檢查內容，再要求確認；還原時會取代目前這份手帳。匯入前另保留一份本機復原副本。</p>${btn('還原上次匯入前的資料','restore-before','','secondary small')}${blocked?btn('下載無法讀取的原始資料','raw-export'):''}</section><section class="card settings-block"><h2>退費與結算</h2><p>依已收款逐筆核定保留費用及實際退費；保留原因與憑證，原收款紀錄不會刪除。退費後收入按退款日扣除。</p><div class="button-row">${btn('店家手動核定','refund-center','','pink')}${btn('查看退費紀錄','refund-history')}</div><p class="hint">核定應依契約及實際履行情況，法律強制規定優先。不自動套用對學員公告的退費比例。</p></section><section class="card settings-block"><h2>收費小卡</h2><div class="setting-row"><div>單堂體驗<small>2 小時，材料另計</small></div><strong>$500／堂</strong></div><div class="setting-row"><div>一週兩堂方案<small>預設週二＋週四，可指定任意兩堂課</small></div><strong>$800／兩堂</strong></div><p class="hint">兩堂方案以「已出席」計算使用堂數。方案費共同記錄，兩堂材料費各自記錄；付款切換會清楚標示影響範圍。</p></section><section class="card settings-block"><h2>加入主畫面</h2><p>iPhone：使用 Safari 開啟 App 的 HTTPS 網址，點「分享」→「加入主畫面」。電腦可在支援的瀏覽器安裝。</p><p id="offline-status">${swReady?'✓ 離線資源已就緒，可離線查看及修改。':location.protocol==='file:'?'目前為本機檔案模式。課程管理可使用；PWA 安裝與離線快取需透過 localhost 或 HTTPS 開啟。':'離線資源尚未就緒，請保持連線完成首次載入。'}</p><small>版本 1.1.0 · 單機手作課程管理</small></section><section class="card settings-block"><h2>示範資料</h2><p>移除示範課程、假學員及收款紀錄。四個課程範本會保留；與正式報名有關的課程及學員也會保留。</p>${btn('移除示範資料','remove-demo','','pink')}</section><section class="card settings-block danger-zone"><h2>清除所有資料</h2><p>清空這個 App 的課程、學員、收款、範本與本機復原副本，不會影響同瀏覽器的其他 App。請先匯出備份。</p>${btn('清除所有資料','clear-all','','danger')}</section>`}
function render(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));document.querySelectorAll('.bottom-nav [data-action=nav]').forEach(el=>{el.classList.toggle('active',el.dataset.value===page);el.setAttribute('aria-current',el.dataset.value===page?'page':'false')});$('#main').innerHTML=({home,courses,students,stats:statsPage,settings}[page]||home)();updateConnection()}
function nav(v){page=v;render();window.scrollTo(0,0)}
function updateConnection(){$('#connection').textContent=navigator.onLine?'● 本機保存':'● 離線使用';if($('#offline-status')&&swReady)$('#offline-status').textContent='✓ 離線資源已就緒，可離線查看及修改。'}
function checklist(c,key,labels){return `<div class="checklist">${labels.map((l,i)=>`<label class="checkbox"><input type="checkbox" data-check="${key}" data-course="${c.id}" data-index="${i}" ${c[key][i]?'checked':''}>${l}</label>`).join('')}</div>`}
function enrollmentCard(e){const s=findStudent(e.studentId),ps=C.relatedPayments(db,e),pending=ps.filter(p=>!p.paid).reduce((a,p)=>a+p.amount,0);return `<article class="enrollment-row ${e.cancelled?'cancelled':''}"><header><button class="text-btn" data-action="student-detail" data-id="${s.id}"><h3>${esc(s.name)}</h3></button>${pill(e.cancelled?'已取消':C.paid(db,e)?'已付款':'未付款')}</header><p class="hint">材料：${esc(e.materialNote||'尚未指定')} ${e.packageId?' · 兩堂方案':''}</p>${ps.some(p=>C.refunded(db,p.id)>0)?`<p class="hint">相關費用已退 ${money(ps.reduce((a,p)=>a+C.refunded(db,p.id),0))}（方案費為兩堂共用）</p>`:''}${e.notes?`<p class="hint">${esc(e.notes)}</p>`:''}${!e.cancelled?`<div class="button-row">${btn(C.paid(db,e)?'✓ 已付款':`□ 付款 ${money(pending)}`,'toggle-paid',e.id,C.paid(db,e)?'secondary':'pink')}${btn(e.attended?'✓ 已出席':'□ 出席','toggle-attended',e.id,e.attended?'secondary':'secondary')}</div><div class="button-row">${btn('材料／備註','edit-enrollment',e.id,'secondary small')}${btn('取消報名','cancel-enrollment',e.id,'secondary small')}</div>`:'<p class="hint">已收款紀錄保留，可至學員的收款明細核對。</p>'}</article>`}
function courseDetail(id){const c=findCourse(id);if(!c)return;const es=C.active(db,id),k=C.kit(db,c),done=countChecks(c.materials);showSheet(c.name,`<div class="detail-top"><div class="course-thumb">${thumb(c)}</div><div><h3>${esc(c.name)}</h3><p class="muted">${shortDate(c.date)} · ${c.start}–${c.end}</p></div></div><div class="detail-facts">${pill(C.status(db,c))}<span>${es.length}／${c.capacity} 人 · ${c.minimum} 人成班</span><span>${esc(c.level)}</span></div><div class="button-row">${btn('編輯課程','edit-course',c.id)}${btn('＋ 新增學員','enroll',c.id,'')}</div><div class="detail-section"><div class="section-head"><h3>本堂學員 <small>${es.length} 位</small></h3><small>${es.filter(e=>!C.paid(db,e)).length} 位待付款</small></div>${es.map(enrollmentCard).join('')||empty('還沒有學員，邀請大家一起來手作。')}</div><section class="detail-section"><div class="section-head"><h3>材料準備</h3><span id="material-count">${pill(done===10?'✓ 材料準備完成':`${done}／10 已完成`)}</span></div><div class="progress-track"><span id="material-progress" style="width:${done*10}%"></span></div>${checklist(c,'materials',C.MATERIALS)}</section><details class="form-section" style="margin-top:22px"><summary>招生前檢查 <span id="prep-count">${countChecks(c.prep)===10?'✓ 可以招生':`${countChecks(c.prep)}／10`}</span></summary><div class="section-body">${checklist(c,'prep',C.PREP)}</div></details><details class="form-section"><summary>課程與材料資訊</summary><div class="section-body"><p>${esc(c.description)}</p><p class="hint">難度：${esc(c.difficulty)} · 適合：${esc(c.level)}</p><hr><h3>${esc(k.name)}</h3><p>${esc(k.contents)}</p><p class="hint">材料售價 ${money(k.price)} · 成本 ${money(k.cost)}</p><hr><p>工具：${esc(c.tools||'未設定')}</p><p class="hint">備註：${esc(c.notes||'無')}</p></div></details>${db.enrollments.some(e=>e.sessionId===id&&e.cancelled)?`<details class="form-section"><summary>已取消的報名</summary><div class="section-body">${db.enrollments.filter(e=>e.sessionId===id&&e.cancelled).map(enrollmentCard).join('')}</div></details>`:''}${btn('產生 LINE 招生資訊','line',c.id,'full secondary')}`,{type:'course',id})}
function studentDetail(id){const s=findStudent(id);if(!s)return;const es=db.enrollments.filter(e=>e.studentId===id),ps=db.payments.filter(p=>p.studentId===id&&!p.void),current=es.filter(e=>!e.cancelled&&!['已完成','取消'].includes(findCourse(e.sessionId).status)&&findCourse(e.sessionId).date>=today()),history=es.filter(e=>!current.includes(e));const list=xs=>xs.map(e=>`<div class="enrollment-row"><button class="text-btn" data-action="course-detail" data-id="${e.sessionId}">${shortDate(findCourse(e.sessionId).date)} ${esc(findCourse(e.sessionId).name)} →</button><div class="meta-line">${pill(e.cancelled?'已取消':C.paid(db,e)?'已付款':'未付款')}<span>${e.attended||e.wasAttended?'✓ 已出席':'尚未出席'}</span></div></div>`).join('');showSheet('學員手帳',`<div class="detail-top"><span class="avatar">${esc(s.name.slice(0,1))}</span><div><h3>${esc(s.name)}</h3><small>${esc(s.nickname||'手作好朋友')} · 已上課 ${es.filter(e=>e.attended||e.wasAttended).length} 堂</small></div></div><p>電話：${esc(s.phone||'未填寫')}</p><p>LINE：${esc(s.lineName||'未填寫')}</p><p class="hint">${esc(s.notes)}</p><div class="detail-facts"><span>累計淨收 ${money(ps.reduce((a,p)=>a+C.paymentNet(db,p),0))}</span><span>待付款 ${money(ps.filter(p=>!p.paid).reduce((a,p)=>a+p.amount,0))}</span></div><div class="button-row">${btn('編輯資料','edit-student',s.id)}${btn('＋ 報名課程','enroll-student',s.id,'')}</div><div class="button-row" style="margin-top:10px">${btn('退費／結算','refund-center',s.id,'pink')}${btn('退費紀錄','refund-history',s.id)}</div>${db.packages.filter(p=>p.studentId===id).map(p=>`<div class="price-box"><strong>兩堂方案${p.closed?'（已結清）':''} · ${C.used(db,p)}／2 已使用</strong><p class="hint">購買日期 ${p.purchasedAt} · ${C.packageEnrollments(db,p).length}／2 堂已指定</p>${p.closed?btn('恢復方案補選','reopen-package',p.id,'secondary small'):''}${C.packageEnrollments(db,p).map(e=>`<p class="hint">${shortDate(findCourse(e.sessionId).date)} ${esc(findCourse(e.sessionId).name)} · ${e.attended||e.wasAttended?'已使用':'待上課'}</p>`).join('')}${!p.closed&&C.packageEnrollments(db,p).length<2?btn('補選課程','enroll-student',s.id,'secondary small'):''}</div>`).join('')}<section class="detail-section"><h3>目前報名</h3>${list(current)||empty('目前沒有待上課程。')}</section><details class="form-section"><summary>歷史課程（${history.length}）</summary><div class="section-body">${list(history)||'<p class="muted">尚無歷史課程。</p>'}</div></details><details class="form-section"><summary>收款明細</summary><div class="section-body">${paymentList(ps)||'<p>尚無收款紀錄</p>'}</div></details>`,{type:'student',id})}
function paymentLabel(p){return p.packageId?'兩堂方案費':p.kind==='tuition'?'單堂課程費':'材料費'}
function refundCenter(sid=''){const ps=db.payments.filter(p=>p.paid&&!p.void&&C.paymentNet(db,p)>0&&(!sid||p.studentId===sid));showSheet('退費／結算',`<p class="hint">先選擇一筆已收款，課程費與材料費分開核定。此處只登記實際退回的款項，不會操作銀行或發送訊息。</p><label style="margin:16px 0">學員<select id="refund-student-filter"><option value="">全部學員</option>${db.students.map(s=>`<option value="${s.id}" ${sid===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${ps.map(p=>`<div class="payment-row"><div class="row-main"><strong>${esc(findStudent(p.studentId).name)}</strong><small>${paymentLabel(p)} · ${p.enrollmentId?esc(findCourse(db.enrollments.find(e=>e.id===p.enrollmentId).sessionId).name):'方案合計 2 堂'}</small><small>可退餘額 ${money(C.paymentNet(db,p))} · 已退 ${money(C.refunded(db,p.id))}</small></div>${btn('試算退費','refund-form',p.id,'pink small')}</div>`).join('')||empty('沒有可退的已收款項。')}`,{type:'refund-center',id:sid})}
function refundForm(pid){const p=db.payments.find(p=>p.id===pid);if(!p||C.paymentNet(db,p)<=0)throw Error('這筆款項已無可退餘額');const es=p.packageId?db.enrollments.filter(e=>e.packageId===p.packageId):db.enrollments.filter(e=>e.id===p.enrollmentId),used=es.filter(e=>e.attended||e.wasAttended).length;const unit=p.packageId?400:500,balance=C.paymentNet(db,p);showSheet('店家手動核定退費',`<form id="refund-form" data-payment="${pid}" data-request="${C.uid()}"><div class="form-error" role="alert"></div><div class="refund-summary"><h3>${esc(findStudent(p.studentId).name)} · ${paymentLabel(p)}</h3><div class="price-line"><span>原收款</span><strong>${money(p.amount)}</strong></div><div class="price-line"><span>先前已退</span><span>${money(C.refunded(db,pid))}</span></div><div class="price-line"><span>目前可退餘額</span><strong>${money(balance)}</strong></div></div><p class="hint">${p.kind==='tuition'?`已記錄 ${used} 堂出席；原方案換算 ${money(unit)}／堂，僅供核對，保留費用由你填寫。兩堂方案不自動追溯改按 $500 單堂計價。`:'已交付或使用的材料，可依契約及實際情況填寫保留金額；未交付、可回收的部分請分開核對。'}</p><details class="form-section" open style="margin-top:18px"><summary>① 核定保留費用</summary><div class="section-body form-grid">${p.kind==='tuition'?field('已提供教學｜保留金額','service',0,'number','required min="0" step="1"'):field('已交付／使用材料｜保留金額','material',0,'number','required min="0" step="1"')}${field('其他實際淨損失｜保留金額','loss',0,'number','required min="0" step="1"')}${textfield('保留理由／契約依據（有保留時必填）','basis','')}${textfield('憑證／紀錄編號（有實際損失時必填）','evidence','')}<p class="hint span-2">可列出授課日期、材料交付或專屬裁切紀錄。損失應扣除可回收、可轉用與省下的費用；同一成本勿重複列入。一般行政費、空位或預期收入不會自動扣款。</p>${p.kind==='material'?`<label class="checkbox span-2"><input type="checkbox" name="materialUsed" ${es[0]?.materialUsed?'checked':''}>材料已交付／使用（即使取消，仍保留原成本紀錄）</label>`:''}</div></details><div class="price-box" id="refund-calculation"></div><details class="form-section" open style="margin-top:18px"><summary>② 實際退款紀錄</summary><div class="section-body form-grid">${field('退款日期','date',today(),'date',`required min="${p.paidAt}" max="${today()}"`)}<label>退款方式<select name="method"><option>現金</option><option>轉帳</option><option>原付款方式</option><option>其他</option></select></label>${textfield('退費原因（必填）','reason','')}${field('退款憑證／備註','reference','','text','maxlength="200"')}<label class="checkbox span-2"><input type="checkbox" name="cancelBooking">${p.packageId?'結清此兩堂方案，取消尚未出席的報名並停止補選':'同時取消這筆費用對應的報名'}</label><p class="hint span-2">${p.packageId?'若是退課結算，請勾選結清方案，避免退費後仍可補選。':'若只提供價格折讓，可保留原報名。'}其他已收材料費仍須逐筆核對退費。</p><label class="checkbox span-2"><input type="checkbox" name="confirmed" required>我已核對金額，並已實際退還這筆款項</label></div></details><details class="form-section"><summary>店家核定提醒</summary><div class="section-body"><p class="hint">此工具整理收款及保留理由，並不判定扣款是否合法。依已提供教學、已交付材料及具依據的實際淨損失核定，可避免店家負擔沒有紀錄的損失。若涉及法定解除、店家停課或補習班規範，請先確認適用規定；不套用一律不退費。</p></div></details><div class="form-actions">${btn('返回','refund-center',p.studentId)}<button class="btn" type="submit">確認已退費並記帳</button></div></form>`);updateRefundQuote()}
function refundInput(form){const f=new FormData(form);return {id:form.dataset.request,paymentId:form.dataset.payment,service:Number(f.get('service')||0),material:Number(f.get('material')||0),loss:Number(f.get('loss')||0),date:String(f.get('date')||''),reason:String(f.get('reason')||''),basis:String(f.get('basis')||''),evidence:String(f.get('evidence')||''),method:String(f.get('method')||''),reference:String(f.get('reference')||''),cancelBooking:f.has('cancelBooking'),materialUsed:f.has('materialUsed'),confirmed:f.has('confirmed')}}
function updateRefundQuote(){const form=$('#refund-form');if(!form)return;try{const v=refundInput(form),q=C.refundQuote(db,v.paymentId,v);$('#refund-calculation').innerHTML=`<div class="price-line"><span>本次核定保留</span><strong>${money(q.retained)}</strong></div><div class="price-line total"><span>本次實際退費</span><strong>${money(q.amount)}</strong></div><p class="hint">可退餘額 ${money(q.available)} − 本次核定保留 ${money(q.retained)}</p>`}catch(e){$('#refund-calculation').textContent=e.message}}
function refundHistory(sid=''){const rs=db.refunds.filter(r=>!sid||r.studentId===sid).slice().sort((a,b)=>(b.date+b.createdAt).localeCompare(a.date+a.createdAt));showSheet('退費紀錄',`${sid?'':`<p class="hint">全期間紀錄。統計按退款日期計入當月；作廢只用於誤登更正，不代表收回已退的款項。</p>`}${rs.map(r=>{const p=db.payments.find(p=>p.id===r.paymentId);return `<article class="enrollment-row ${r.voided?'cancelled':''}" style="margin-top:15px"><header><strong>${esc(findStudent(r.studentId).name)} · ${money(r.amount)}</strong>${pill(r.voided?'已作廢':'已退費')}</header><p class="hint">${r.date} · ${paymentLabel(p)} · ${esc(r.method)}</p><p>${esc(r.reason)}</p><details style="margin-top:10px"><summary>核定明細</summary><div class="hint">原收 ${money(p.amount)} · 當時可退 ${money(r.availableBefore)}<br>教學保留 ${money(r.service)} · 材料保留 ${money(r.material)} · 實際損失 ${money(r.loss)}<br>依據：${esc(r.basis||'無保留費用')}<br>憑證：${esc(r.evidence||'未填')}<br>退款備註：${esc(r.reference||'無')}<br>${r.cancelBooking?'登記時已取消報名／結清方案':'原報名保留'}</div></details>${r.voided?`<p class="hint">${r.voidedAt} 更正：${esc(r.voidReason)}</p>`:`<div class="button-row" style="margin-top:12px">${btn('複製退費明細','copy-refund',r.id,'secondary small')}${btn('更正誤登','void-refund',r.id,'secondary small')}</div>`}</article>`}).join('')||empty('目前沒有退費紀錄。')}`,{type:'refund-history',id:sid})}
function refundText(r){const p=db.payments.find(p=>p.id===r.paymentId);return `采卉布藝｜退費結算明細\n學員：${findStudent(r.studentId).name}\n項目：${paymentLabel(p)}\n原收款：${money(p.amount)}\n本次結算前餘額：${money(r.availableBefore)}\n保留教學：${money(r.service)}\n保留材料：${money(r.material)}\n實際淨損失：${money(r.loss)}\n核定依據：${r.basis||'無保留費用'}\n憑證／紀錄：${r.evidence||'未填'}\n本次實際退費：${money(r.amount)}\n日期／方式：${r.date}／${r.method}\n原因：${r.reason}\n備註：${r.reference||'無'}\n${r.cancelBooking?'已依勾選取消報名或結清方案。':'原報名保留。'}\n本明細供雙方核對，不排除依法享有的權利。`}

function paymentList(ps){return ps.map(p=>{const e=p.enrollmentId?db.enrollments.find(e=>e.id===p.enrollmentId):null,c=e?findCourse(e.sessionId):null,returned=C.refunded(db,p.id);return `<div class="payment-row"><div class="row-main">${paymentLabel(p)} ${money(p.amount)}<small>${c?esc(c.name)+' · '+shortDate(c.date):'方案費僅收一次'}${e?.cancelled?' · 報名已取消':''}</small><small>${p.paid?'收款日 '+p.paidAt:'尚未收款'}</small>${returned?`<small>已退 ${money(returned)} · 淨收 ${money(C.paymentNet(db,p))}</small>`:''}</div><div class="payment-actions">${btn(p.paid?'已收款':'收款','payment-toggle',p.id,p.paid?'secondary small':'pink small')}${p.paid&&C.paymentNet(db,p)>0?btn('退費／結算','refund-form',p.id,'pink small'):''}</div></div>`}).join('')}
function unpaid(){const ps=db.payments.filter(p=>!p.paid&&!p.void);showSheet('待收款明細',ps.length?db.students.filter(s=>ps.some(p=>p.studentId===s.id)).map(s=>`<section class="detail-section"><button class="text-btn" data-action="student-detail" data-id="${s.id}"><h3>${esc(s.name)} →</h3></button>${paymentList(ps.filter(p=>p.studentId===s.id))}</section>`).join(''):empty('目前沒有待收款，辛苦了 ♡'),{type:'unpaid'})}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function textfield(label,name,value=''){return `<label class="span-2">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function formError(form,e){form.querySelector('.form-error').textContent=e.message;form.querySelector('.form-error').scrollIntoView({block:'nearest'})}
function courseForm({id=null,templateId=null,date=today(),isTemplate=false}={}){const original=id?(isTemplate?db.templates:db.sessions).find(c=>c.id===id):null,t=original||(templateId?db.templates.find(t=>t.id===templateId):null),k=t?C.kit(db,t):{name:'',contents:'',price:150,cost:80},v=t||{name:'',date,start:'13:00',end:'15:00',capacity:4,minimum:2,level:'零基礎',difficulty:'★ 簡單',description:'',tools:'縫紉機、剪刀、尺、熨斗（店內提供）',notes:'',photo:''};editing={id,templateId:templateId||original?.templateId,isTemplate};formPhoto=v.photo;showSheet(isTemplate?(id?'編輯課程範本':'新增課程範本'):(id?'編輯課程':'安排新的手作課'),`<form id="course-form"><div class="form-error" role="alert"></div>${!id&&!isTemplate?`<label style="margin-bottom:18px">從範本開始<select id="template-select"><option value="">自訂課程</option>${db.templates.map(t=>`<option value="${t.id}" ${t.id===templateId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`:''}<details class="form-section" open><summary>① 基本資訊</summary><div class="section-body form-grid"><label class="span-2">課程名稱<input name="name" value="${esc(v.name)}" required maxlength="100" placeholder="例如：束口收納袋"></label>${!isTemplate?field('開課日期','date',original?.date||date,'date','required'):''}${!isTemplate?`<label>課程狀態<select name="status">${C.STATUS.map(s=>`<option ${s===(original?.status||'準備招生')?'selected':''}>${s}</option>`).join('')}</select></label>`:''}${field('開始時間','start',v.start,'time','required')}${field('結束時間','end',v.end,'time','required')}${field('人數上限','capacity',v.capacity,'number','required min="1" max="100" step="1"')}${field('最低成班人數','minimum',v.minimum,'number','required min="1" max="100" step="1"')}<label class="span-2">作品照片<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp"><small>一張照片，自動縮小至最長邊 1,000 px；支援 JPG／PNG／WebP，原檔最多 10 MB。</small></label><div id="form-photo" class="photo-field span-2">${photoFormPreview()}</div></div></details><details class="form-section"><summary>② 收費</summary><div class="section-body"><p>單堂 $500／2 小時</p><p>兩堂方案 $800／共 4 小時</p><p class="hint">材料費另外計算。請在新增報名時選擇方案，並指定課程；兩堂方案費只記錄一次。</p></div></details><details class="form-section"><summary>③ 材料包</summary><div class="section-body form-grid"><label class="span-2">材料包名稱<input name="kitName" value="${esc(k.name)}" placeholder="例如：束口袋材料包" required></label>${field('材料成本（每人）','cost',k.cost,'number','required min="0" max="1000000" step="1"')}${field('材料售價（每人）','price',k.price,'number','required min="0" max="1000000" step="1"')}${textfield('材料包內容','contents',k.contents)}${original?'<p class="hint span-2">修改只套用於之後的新報名，既有報名費用與成本保持原紀錄。</p>':''}</div></details><details class="form-section"><summary>④ 教學準備${!isTemplate?` · ${countChecks(original?.prep||[])}/10`:''}</summary><div class="section-body form-grid">${field('難度','difficulty',v.difficulty)}${field('適合程度','level',v.level)}${textfield('課程說明','description',v.description)}${textfield('需要工具','tools',v.tools)}${!isTemplate?`<div class="span-2"><h3>招生前檢查</h3>${C.PREP.map((l,i)=>`<label class="checkbox"><input type="checkbox" name="prep${i}" ${original?.prep[i]?'checked':''}>${l}</label>`).join('')}</div>`:''}</div></details><details class="form-section"><summary>⑤ 其他設定</summary><div class="section-body">${textfield('備註','notes',v.notes)}${isTemplate?field('材料費參考（文字）','reference',v.reference||''):''}<p class="hint">「招生中」依報名人數自動判定成班／額滿；也可手動指定狀態。手動設為「已額滿」會停止接受報名。</p></div></details><div class="form-actions">${btn('取消','close')}<button class="btn" type="submit">${isTemplate?'儲存範本':'儲存課程'}</button></div></form>`);}
function photoFormPreview(){return formPhoto?`<button type="button" class="photo-btn" data-action="form-photo"><img src="${esc(formPhoto)}" alt="剛上傳的作品照片，點擊放大"></button>${btn('移除照片','remove-photo','','secondary small')}`:'<p class="hint">尚未加入照片，將使用手作插畫。</p>'}
function studentForm(id=null,back=null){const s=id?findStudent(id):{name:'',nickname:'',phone:'',lineName:'',notes:''};showSheet(id?'編輯學員':'認識一位新學員',`<form id="student-form" data-id="${id||''}" data-back="${back||''}"><div class="form-error" role="alert"></div><div class="form-grid"><label class="span-2">姓名<input name="name" value="${esc(s.name)}" required maxlength="100" placeholder="如何稱呼這位學員？"></label>${field('暱稱','nickname',s.nickname)}${field('電話','phone',s.phone,'tel')}${field('LINE 名稱','lineName',s.lineName)}${textfield('備註','notes',s.notes)}</div><div class="form-actions">${btn('取消','close')}<button class="btn" type="submit">${back?'儲存並繼續報名':'儲存學員'}</button></div></form>`)}
function availableCourses(studentId=null){return db.sessions.filter(c=>!['取消','已完成','未開課','已額滿'].includes(c.status)&&C.active(db,c.id).length<c.capacity&&(!studentId||!C.active(db,c.id).some(e=>e.studentId===studentId))).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))}
function courseOptions(cs,chosen,placeholder='請選擇課程'){return `<option value="">${placeholder}</option>${cs.map(c=>`<option value="${c.id}" ${c.id===chosen?'selected':''}>${shortDate(c.date)} ${esc(c.name)} · ${C.active(db,c.id).length}/${c.capacity}人</option>`).join('')}`}
function enrollmentForm(cid=null,sid=null){const cs=availableCourses(sid),chosen=cs.some(c=>c.id===cid)?cid:(sid?cs[0]?.id:null),pkgs=db.packages.filter(p=>(!sid||p.studentId===sid)&&!p.closed&&C.packageEnrollments(db,p).length<2);showSheet('新增課程報名',`<form id="enroll-form"><div class="form-error" role="alert"></div><div class="form-grid"><label class="span-2">報名學員<select name="studentId" required id="enroll-student"><option value="">請選擇學員</option>${db.students.map(s=>`<option value="${s.id}" ${s.id===sid?'selected':''}>${esc(s.name)}${s.nickname?'（'+esc(s.nickname)+'）':''}</option>`).join('')}</select></label><div class="span-2">${btn('＋ 先建立新學員','new-student-back',chosen||cid||'none','secondary small')}</div><label class="span-2">收費方案<select name="plan" id="enroll-plan"><option value="single">單堂體驗 $500</option><option value="pair">兩堂方案 $800（指定兩堂）</option><option value="existing">使用既有方案空位（不重收方案費）</option></select></label><label class="span-2" id="existing-package-label" hidden>既有方案<select name="packageId" id="existing-package"><option value="">請先選擇學員</option>${pkgs.filter(p=>p.studentId===sid).map(p=>`<option value="${p.id}">${p.purchasedAt} 購買 · 已使用 ${C.used(db,p)}/2</option>`).join('')}</select></label><label class="span-2">第一堂課<select name="firstId" id="enroll-first" required>${courseOptions(cs,chosen)}</select></label><label class="span-2" id="second-course-label" hidden>第二堂課<select name="secondId" id="enroll-second">${courseOptions(cs,null,'請指定第二堂（不可相同）')}</select></label>${field('購買／報名日期','purchasedAt',today(),'date','required')}${field('材料顏色／款式','materialNote','','text','placeholder="例如：粉色"')}${textfield('報名備註','notes','')}</div><div class="price-box" id="enroll-price"></div><p class="hint">方案費只收一次。每堂材料費分開記錄；出席勾選才會計入已使用堂數。</p><label class="checkbox"><input name="paid" type="checkbox">已收取本次全部費用</label><div class="form-actions">${btn('取消','close')}<button class="btn" type="submit">確認報名</button></div></form>`);updateEnrollmentPrice()}
function updateEnrollmentPrice(){const form=$('#enroll-form');if(!form)return;const data=new FormData(form),plan=data.get('plan');$('#second-course-label').hidden=plan!=='pair';$('#enroll-second').required=plan==='pair';$('#existing-package-label').hidden=plan!=='existing';$('#existing-package').required=plan==='existing';const c1=findCourse(data.get('firstId')),c2=plan==='pair'?findCourse(data.get('secondId')):null;const tuition=plan==='pair'?800:plan==='single'?500:0;let html=`<div class="price-line"><span>${plan==='pair'?'兩堂方案費':plan==='existing'?'既有方案 · 不重收':'單堂課程費'}</span><strong>${money(tuition)}</strong></div>`;for(const [i,c] of [c1,c2].entries())if(c)html+=`<div class="price-line"><span>第${i+1}堂材料 · ${esc(C.kit(db,c).name)}</span><span>${money(C.kit(db,c).price)}</span></div>`;html+=`<div class="price-line total"><span>本次應收</span><span>${money(tuition+[c1,c2].filter(Boolean).reduce((a,c)=>a+C.kit(db,c).price,0))}</span></div>`;if(plan==='existing'){const p=db.payments.find(p=>p.packageId===data.get('packageId'));if(p&&!p.paid)html+='<p class="hint">另有既有方案費 $800 尚未收款；本次勾選只收取新增材料费，原方案費請至付款明細處理。</p>'}$('#enroll-price').innerHTML=html}
function enrollmentEdit(id){const e=db.enrollments.find(e=>e.id===id);showSheet('材料與報名備註',`<form id="enrollment-edit-form" data-id="${id}"><div class="form-error" role="alert"></div>${field('材料顏色／款式','materialNote',e.materialNote)}${textfield('備註','notes',e.notes)}<label class="checkbox"><input name="materialUsed" type="checkbox" ${e.materialUsed?'checked':''}>材料已交付／使用</label><div class="form-actions">${btn('取消','course-detail',e.sessionId)}<button class="btn" type="submit">儲存備註</button></div></form>`)}
function lineCopy(id){const c=findCourse(id),k=C.kit(db,c),remaining=Math.max(0,c.capacity-C.active(db,id).length);const text=`🧵 采卉手作時光\n\n｜${c.name}｜\n\n📅 ${shortDate(c.date)}\n⏰ ${c.start}–${c.end}\n👥 小班 ${c.minimum}–${c.capacity} 人\n\n課程費：\n單堂 $500\n\n兩堂方案：\n$800／兩堂（需指定兩堂課，材料另計）\n\n材料包：\n${money(k.price)}\n\n本堂單堂總費用：\n${money(500+k.price)}\n\n${c.level==='零基礎'?'零基礎也可以參加 ♡':'適合'+c.level+'的朋友 ♡'}\n\n剩餘名額：\n${remaining} 位${remaining===0?'（目前額滿）':''}\n\n有興趣歡迎直接 LINE 回覆報名。`;showSheet('LINE 招生資訊',`${['取消','已完成','未開課'].includes(c.status)?'<p class="warning">此課程目前'+esc(c.status)+'，請確認狀態後再分享。</p>':''}<label>可直接修改後複製<textarea id="line-text" class="line-copy">${esc(text)}</textarea></label><div class="form-actions">${btn('返回課程','course-detail',id)}${btn('複製文案','copy-line','','')}</div>`)}
function download(value,name,type='application/json'){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportData(){download(JSON.stringify({app:'caihui-craft',exportedAt:new Date().toISOString(),data:db},null,2),`采卉手作-備份-${today()}.json`);toast('備份已下載，請妥善保存')}
function importData(raw){const parsed=JSON.parse(raw),next=C.validate(parsed.data||parsed);if(!confirm(`確認還原備份？\n${next.sessions.length} 堂課、${next.students.length} 位學員、${next.enrollments.length} 筆報名。\n這會取代目前資料。建議先匯出備份。`))return;const before=localStorage.getItem(C.KEY);if(before)localStorage.setItem(C.KEY+'-before-import',before);next.revision=db.revision+1;localStorage.setItem(C.KEY,JSON.stringify(next));db=next;blocked=false;warning('');render();toast('備份已還原')}
function refreshModal(){if(modalContext?.type==='course')courseDetail(modalContext.id);else if(modalContext?.type==='student')studentDetail(modalContext.id);else if(modalContext?.type==='unpaid')unpaid();else if(modalContext?.type==='refund-center')refundCenter(modalContext.id);else if(modalContext?.type==='refund-history')refundHistory(modalContext.id)}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const {action,id,value}=target.dataset;try{switch(action){
case 'nav':nav(value);break;
case 'stats-select-month':statsMonth=id;render();break;
case 'refund-center':refundCenter(id||'');break;
case 'refund-form':refundForm(id);break;
case 'refund-history':refundHistory(id||'');break;
case 'copy-refund':{const r=db.refunds.find(r=>r.id===id);showSheet('退費結算明細',`<label>核對後可複製給學員<textarea id="line-text" class="line-copy">${esc(refundText(r))}</textarea></label><div class="form-actions">${btn('返回紀錄','refund-history',r.studentId)}${btn('複製明細','copy-line','','')}</div>`);break}
case 'void-refund':{const r=db.refunds.find(r=>r.id===id);showSheet('更正誤登退費',`<p>僅用於沒有實際退款卻誤登的情況，原紀錄會保留。更正不會自動恢復報名或重新開放已結清方案。</p><form id="void-refund-form" data-id="${id}"><div class="form-error" role="alert"></div>${textfield('更正原因（必填）','reason','')}<label class="checkbox"><input name="confirmed" type="checkbox" required>已確認這是記帳更正，並非向學員收回退款</label><div class="form-actions">${btn('返回','refund-history',r.studentId)}<button class="btn danger" type="submit">確認作廢誤登紀錄</button></div></form>`);break}
case 'reopen-package':{const p=db.packages.find(p=>p.id===id),pay=db.payments.find(x=>x.packageId===id);if(C.refunded(db,pay.id)>0)throw Error('方案仍有有效退費，不能恢復免費補選；請另行報名。');if(confirm('確認恢復這個方案的補選資格？已取消的課程需重新選擇，不會自動恢復。')){commit(d=>{d.packages.find(x=>x.id===id).closed=false});studentDetail(p.studentId)}break}

case 'close':closeSheet();break;
case 'add-menu':showSheet('今天想做點什麼？',`<div class="mini-list">${btn('＋ 安排新的課程','new-course','','full')}${btn('＋ 認識一位新學員','new-student','','full secondary')}${btn('＋ 學員報名課程','enroll','','full secondary')}</div>`);break;
case 'new-course':courseForm();break;case 'new-course-date':courseForm({date:id});break;case 'edit-course':courseForm({id});break;case 'new-template':courseForm({isTemplate:true});break;case 'edit-template':courseForm({id,isTemplate:true});break;case 'use-template':courseForm({templateId:id});break;
case 'course-detail':courseDetail(id);break;case 'course-tab':courseTab=value;render();break;case 'calendar':courseTab='calendar';nav('courses');break;
case 'month-prev':case 'month-next':{const d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()+(action==='month-prev'?-1:1));calendarMonth=C.date(d).slice(0,7);selectedDate=calendarMonth+'-01';render();break}case 'select-date':selectedDate=id;render();break;
case 'new-student':studentForm();break;case 'new-student-back':studentForm(null,id);break;case 'edit-student':studentForm(id);break;case 'student-detail':studentDetail(id);break;
case 'enroll':enrollmentForm(id||null);break;case 'enroll-student':enrollmentForm(null,id);break;
case 'toggle-attended':{const e=db.enrollments.find(e=>e.id===id);commit(d=>{const x=d.enrollments.find(e=>e.id===id);x.attended=!x.attended});courseDetail(e.sessionId);toast('出席紀錄已更新');break}
case 'toggle-paid':{const e=db.enrollments.find(e=>e.id===id),toPaid=!C.paid(db,e),ps=C.relatedPayments(db,e).filter(p=>p.paid!==toPaid);const note=e.packageId?'\n方案費由兩堂課共用，此處只切換方案費及本堂材料費。另一堂材料費保持原狀。':'';if(confirm(`${toPaid?'確認已收到':'改為未付款'} ${money(ps.reduce((a,p)=>a+p.amount,0))}？${note}`)){commit(d=>C.setPaid(d,id,toPaid));courseDetail(e.sessionId);toast('付款紀錄已更新')}break}
case 'payment-toggle':{const p=db.payments.find(p=>p.id===id);if(confirm(`${p.paid?'將這筆收款改為未收款（僅更正記錄，不代表執行退款）':'確認已收到'} ${money(p.amount)}？${p.packageId?'\n此為共用方案費，只會記錄一次。':''}`)){commit(d=>{const x=d.payments.find(p=>p.id===id);C.setPaymentPaid(d,id,!x.paid)});refreshModal();toast('收款紀錄已更新')}break}
case 'cancel-enrollment':{const e=db.enrollments.find(e=>e.id===id);if(confirm('確認取消這位學員的報名？\n名額會釋出、出席會取消。已收款保留供核對；未收的本堂費用作廢。兩堂方案尚未使用的空位可補選其他課程。')){commit(d=>C.cancel(d,id));courseDetail(e.sessionId);toast('報名已取消')}break}
case 'edit-enrollment':enrollmentEdit(id);break;case 'unpaid':unpaid();break;case 'line':lineCopy(id);break;
case 'copy-line':{const ta=$('#line-text');try{await navigator.clipboard.writeText(ta.value);toast('已複製，貼到 LINE 就可以了')}catch{ta.focus();ta.select();toast('請長按選取的文字，選擇「複製」')}break}
case 'photo':{const c=db.sessions.find(c=>c.id===id)||db.templates.find(c=>c.id===id);openPhoto(c.photo);break}case 'form-photo':openPhoto(formPhoto);break;case 'close-photo':$('#photo-viewer').close();break;case 'remove-photo':formPhoto='';$('#form-photo').innerHTML=photoFormPreview();break;
case 'export':exportData();break;case 'raw-export':download(localStorage.getItem(C.KEY)||'',`采卉手作-原始資料-${today()}.json`);break;case 'import':$('#import-file').value='';$('#import-file').click();break;
case 'restore-before':{const raw=localStorage.getItem(C.KEY+'-before-import');if(!raw)throw Error('目前沒有匯入前的復原副本');importData(raw);break}
case 'remove-demo':if(confirm('移除示範課程、假學員與其收款紀錄？正式資料及四個課程範本會保留。')){commit(C.removeDemo);toast('示範資料已移除')}break;
case 'clear-all':if(confirm('第一步：確定清除這個 App 的所有資料？請先下載備份。')){showSheet('再次確認清除資料',`<p>此操作會清空課程、學員、付款與範本。重新整理不會再自動加入示範資料。</p><form id="clear-form"><div class="form-error" role="alert"></div><label style="margin-top:20px">請輸入「清除」<input name="confirmText" autocomplete="off" required pattern="清除"></label><div class="form-actions">${btn('保留資料','close')}<button type="submit" class="btn danger">永久清除</button></div></form>`)}break;
}}catch(e){toast(e.message)}});
function openPhoto(src){$('#preview-image').src=src;$('#photo-viewer').showModal()}
$('#preview-image').addEventListener('error',()=>toast('照片無法開啟，請重新上傳有效圖片。'));
document.addEventListener('input',event=>{if(event.target.closest('#refund-form'))updateRefundQuote();if(event.target.id==='course-search'){search=event.target.value;$('#course-results').innerHTML=courseResults()}if(event.target.id==='student-search'){studentSearch=event.target.value;$('#student-results').innerHTML=studentResults()}});
document.addEventListener('change',async event=>{const el=event.target;try{
if(el.id==='refund-student-filter'){refundCenter(el.value)}
if(el.id==='course-filter'){filter=el.value;render()}
if(el.id==='stats-month'){statsMonth=el.value||today().slice(0,7);render()}
if(el.id==='template-select'){const current=$('#course-form [name=date]').value;courseForm({templateId:el.value||null,date:current})}
if(el.dataset.check){const key=el.dataset.check,cid=el.dataset.course,index=+el.dataset.index,checked=el.checked;try{commit(d=>d.sessions.find(c=>c.id===cid)[key][index]=checked)}catch(e){el.checked=!checked;throw e}const c=findCourse(cid);$('#material-count').innerHTML=pill(countChecks(c.materials)===10?'✓ 材料準備完成':`${countChecks(c.materials)}／10 已完成`);$('#material-progress').style.width=countChecks(c.materials)*10+'%';$('#prep-count').textContent=countChecks(c.prep)===10?'✓ 可以招生':`${countChecks(c.prep)}／10`;toast('準備進度已儲存')}
if(el.closest('#enroll-form')){if(el.id==='enroll-student'){const sid=el.value,cs=availableCourses(sid);for(const sel of [$('#enroll-first'),$('#enroll-second')]){const v=sel.value;sel.innerHTML=courseOptions(cs,v)}$('#existing-package').innerHTML='<option value="">請選擇可用方案</option>'+db.packages.filter(p=>p.studentId===sid&&!p.closed&&C.packageEnrollments(db,p).length<2).map(p=>`<option value="${p.id}">${p.purchasedAt} 購買 · 已使用 ${C.used(db,p)}/2</option>`).join('')}updateEnrollmentPrice()}
if(el.id==='photo-input'){const f=el.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('請選擇 10 MB 以下的 JPG、PNG 或 WebP');const form=el.closest('form'),submit=form.querySelector('[type=submit]');submit.disabled=true;toast('正在整理照片…');try{const src=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('無法讀取照片'));r.readAsDataURL(f)});const image=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(Error('照片格式無法開啟'));im.src=src});const canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let quality=.82,photo=canvas.toDataURL('image/jpeg',quality);while(photo.length>280000&&quality>.3){quality-=.1;photo=canvas.toDataURL('image/jpeg',quality)}if(photo.length>450000)throw Error('這張照片細節較多，請先縮小再上傳');if(form.isConnected){formPhoto=photo;$('#form-photo').innerHTML=photoFormPreview();toast('照片已加入，儲存課程後保留')}}finally{submit.disabled=false}}
if(el.id==='import-file'){const f=el.files[0];if(f){if(f.size>8*1024*1024)throw Error('備份檔過大（上限 8 MB）');importData(await f.text())}}
}catch(e){toast(e.message)}});
document.addEventListener('invalid',event=>{let node=event.target.parentElement;while(node){if(node.tagName==='DETAILS')node.open=true;node=node.parentElement}},true);
document.addEventListener('submit',event=>{const form=event.target;if(!form.id)return;event.preventDefault();const f=new FormData(form),str=k=>String(f.get(k)||'').trim();try{switch(form.id){
case 'refund-form':{const v=refundInput(form),q=C.refundQuote(db,v.paymentId,v);if(q.amount<=0)throw Error('試算為 0 元，沒有實際款項可退');if(!confirm(`確認已實際退還 ${money(q.amount)}？\n${v.cancelBooking?'將依勾選取消報名或結清方案。':'保留原報名。'}原收款不會刪除。`))return;const button=form.querySelector('[type=submit]');button.disabled=true;try{commit(d=>C.postRefund(d,v));const p=db.payments.find(p=>p.id===v.paymentId);refundHistory(p.studentId);toast('退費已記帳，統計已扣除')}finally{button.disabled=false}break}
case 'void-refund-form':{const r=db.refunds.find(r=>r.id===form.dataset.id);if(!f.has('confirmed'))throw Error('請先確認更正性質');commit(d=>C.voidRefund(d,r.id,str('reason')));refundHistory(r.studentId);toast('誤登紀錄已作廢並保留查核');break}
case 'course-form':{const {id,isTemplate,templateId}=editing,existing=id?(isTemplate?db.templates:db.sessions).find(c=>c.id===id):null;if(!str('name'))throw Error('請填寫課程名稱');if(str('start')>=str('end'))throw Error('結束時間必須晚於開始時間');if(+f.get('minimum')>+f.get('capacity'))throw Error('最低成班人數不能大於上限');if(existing&&!isTemplate&&C.active(db,id).length>+f.get('capacity'))throw Error('上限不可少於已報名人數');if(!isTemplate&&str('status')==='取消'&&existing&&existing.status!=='取消'&&!confirm('取消整堂課？所有有效報名都會取消；已收款保留供核對，兩堂方案尚未使用的空位可補選其他課程。'))return;let savedId=id||C.uid();commit(d=>{const ks=existing?d.materialKits.find(k=>k.id===existing.kitId):{id:C.uid()},c={...(existing||{}),id:savedId,name:str('name'),start:str('start'),end:str('end'),minimum:+f.get('minimum'),capacity:+f.get('capacity'),level:str('level'),difficulty:str('difficulty'),description:str('description'),tools:str('tools'),notes:str('notes'),photo:formPhoto,kitId:ks.id};Object.assign(ks,{name:str('kitName'),cost:+f.get('cost'),price:+f.get('price'),contents:str('contents')});if(!existing)d.materialKits.push(ks);if(isTemplate)c.reference=str('reference');else Object.assign(c,{date:str('date'),status:str('status'),templateId:templateId||null,prep:C.PREP.map((_,i)=>f.has('prep'+i)),materials:existing?.materials||C.MATERIALS.map(()=>false)});const list=isTemplate?d.templates:d.sessions;if(existing)list[list.findIndex(x=>x.id===id)]=c;else list.push(c);if(!isTemplate&&c.status==='取消')d.enrollments.filter(e=>e.sessionId===savedId&&!e.cancelled).forEach(e=>C.cancel(d,e.id))});$('#sheet').close();if(!isTemplate)courseDetail(savedId);else{courseTab='templates';nav('courses')}toast('已儲存'+(isTemplate?'範本':'課程'));break}
case 'student-form':{if(!str('name'))throw Error('請填寫學員姓名');const id=form.dataset.id||C.uid();commit(d=>{const s={id,name:str('name'),nickname:str('nickname'),phone:str('phone'),lineName:str('lineName'),notes:str('notes')},i=d.students.findIndex(s=>s.id===id);if(i>=0)d.students[i]={...d.students[i],...s};else d.students.push(s)});$('#sheet').close();if(form.dataset.back)enrollmentForm(form.dataset.back==='none'?null:form.dataset.back,id);else studentDetail(id);toast('學員已儲存');break}
case 'enroll-form':{const plan=str('plan'),ids=plan==='pair'?[str('firstId'),str('secondId')]:[str('firstId')];if(ids.some(id=>!id))throw Error('請先指定課程');commit(d=>C.enroll(d,{studentId:str('studentId'),plan,sessionIds:ids,packageId:str('packageId'),purchasedAt:str('purchasedAt'),materialNote:str('materialNote'),notes:str('notes'),paid:f.has('paid')}));$('#sheet').close();courseDetail(ids[0]);toast('報名完成，費用已記錄');break}
case 'enrollment-edit-form':{const id=form.dataset.id,e=db.enrollments.find(e=>e.id===id);commit(d=>{const x=d.enrollments.find(e=>e.id===id);x.materialNote=str('materialNote');x.notes=str('notes');x.materialUsed=f.has('materialUsed')});courseDetail(e.sessionId);toast('備註已儲存');break}
case 'clear-form':{if(str('confirmText')!=='清除')throw Error('請輸入「清除」再繼續');const next=C.blank();next.revision=db.revision+1;localStorage.setItem(C.KEY,JSON.stringify(next));localStorage.removeItem(C.KEY+'-before-import');db=next;blocked=false;warning('');$('#sheet').close();nav('home');toast('所有資料已清空');break}
}}catch(e){formError(form,e)}});
$('#sheet').addEventListener('cancel',event=>{if($('#sheet form')){event.preventDefault();closeSheet()}});
window.addEventListener('storage',event=>{if(event.key!==C.KEY)return;if($('#sheet').open){warning('另一個分頁已更新資料。請關閉目前表單並重新整理，以免覆蓋新資料。');return}try{if(!event.newValue)throw Error('資料已被其他分頁清除，請重新整理');db=C.validate(JSON.parse(event.newValue));render();toast('已讀取另一個分頁的更新')}catch(e){warning(e.message)}});
window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);
load();render();
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{swReady=true;updateConnection()}).catch(()=>{if(page==='settings')render();toast('離線快取尚未就緒，可稍後連線重新開啟')})}
